// Token-based SPA sketch; transport and response types are project-specific.
let refreshInFlight: Promise<string> | null = null;

function getFreshAccessToken(): Promise<string> {
  if (!refreshInFlight) {
    refreshInFlight = requestRefreshToken()
      .then(({ accessToken }) => accessToken)
      .finally(() => {
        refreshInFlight = null;
      });
  }
  return refreshInFlight;
}

async function sendWithOneRefresh(
  request: ApiRequest,
): Promise<ApiResponse> {
  const first = await send(request);
  if (first.status !== 401 || request.authRetry || request.skipRefresh) {
    return first;
  }

  try {
    const accessToken = await getFreshAccessToken();
    return send({ ...request, accessToken, authRetry: true });
  } catch {
    clearClientAuthState();
    return { status: 401, body: { error: 'reauthentication-required' } };
  }
}
